from (values
('127.30.d.1.A',2,'Which is an entrepreneurship opportunity in agriculture?','["starting a farm stand that sells local produce", "avoiding all risk", "waiting for a job to appear", "only reading about crops"]'::jsonb,0,'Entrepreneurs start and run agricultural businesses.','original'),
('127.30.d.1.A',2,'Education beyond high school in agriculture can lead to careers such as:','["jewelry designer", "agronomist or animal scientist", "airline pilot only", "court reporter"]'::jsonb,1,'Postsecondary study opens science careers.','original'),
('127.30.d.1.B',2,'Solving a problem in an agricultural workplace begins with:','["ignoring the cause", "blaming a coworker", "identifying the problem and gathering information", "guessing quickly"]'::jsonb,2,'Problem solving starts with clear understanding.','original'),
('127.30.d.1.B',2,'Critical thinking on a farm means:','["acting without information", "avoiding choices", "copying others blindly", "weighing evidence before making a decision"]'::jsonb,3,'Careful analysis leads to better decisions.','original'),
('127.30.d.1.C',2,'A worker using a power tool on a farm should wear:','["safety glasses and hearing protection", "sandals and headphones", "loose jewelry", "no protective gear"]'::jsonb,0,'PPE prevents common injuries.','original'),
('127.30.d.1.C',2,'Handling livestock safely requires:','["sudden shouting", "calm movements and knowledge of animal behavior", "ignoring warning signs", "standing behind animals"]'::jsonb,1,'Safe handling reduces injuries.','original'),
